from collections import defaultdict, deque
from typing import List


class Solution:
    def numBusesToDestination(
        self, routes: List[List[int]], source: int, target: int
    ) -> int:
        if source == target:
            return 0

        d = defaultdict(list)
        for i, r in enumerate(routes):
            for v in r:
                d[v].append(i)

        if source not in d or target not in d:
            return -1

        # Early exit: target reachable from a source bus?
        for i in d[source]:
            if target in routes[i]:
                return 1

        vis_bus = set(d[source])
        vis_stop = {source}
        q = deque(d[source])
        ans = 1

        while q:
            ans += 1
            for _ in range(len(q)):
                bus = q.popleft()
                for stop in routes[bus]:
                    if stop in vis_stop:
                        continue
                    vis_stop.add(stop)
                    if stop == target:
                        return ans
                    for nb in d[stop]:
                        if nb not in vis_bus:
